#[derive(Clone, Copy, Debug)]
enum TuMonkStep {
    Start,
    OnTouch,
}

fn tu_monk_run(ctx: &Ctx, mut step: TuMonkStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            TuMonkStep::Start => {
                step = TuMonkStep::OnTouch;
                continue 'machine;
            }
            TuMonkStep::OnTouch => {
                if ctx.var("BaseJob").get()?.loosely_equals(&ctx.constant("JOB_ACOLYTE")?) {
                    'b1: {
                        let subject1 = ctx.var("tu_acolyte01").get()?;
                        let mut matched1 = false;
                        let no_case1 = !subject1.loosely_equals(&Val::from(4))
                            && !subject1.loosely_equals(&Val::from(10))
                            && !subject1.loosely_equals(&Val::from(25));
                        if !matched1 && subject1.loosely_equals(&Val::from(4)) {
                            matched1 = true;
                        }
                        if !matched1 && subject1.loosely_equals(&Val::from(10)) {
                            matched1 = true;
                        }
                        if !matched1 && subject1.loosely_equals(&Val::from(25)) {
                            matched1 = true;
                        }
                        if matched1 {
                            ctx.lines_as("Sound by Window", args!["..."])?;
                            ctx.next()?;
                            ctx.lines(args![
                                "^3355FFThere's some kind",
                                "of noise coming from",
                                "yonder window...^000000"
                            ])?;
                            ctx.close_window()?;
                            return Err(Stop::End);
                        }
                    }
                }
                return Err(Stop::End);
            }
        }
    }
}

pub fn tu_monk(ctx: &Ctx) -> Script {
    tu_monk_run(ctx, TuMonkStep::Start, Vec::new()).map(|_| ())
}

pub fn tu_monk_ontouch(ctx: &Ctx) -> Script {
    tu_monk_run(ctx, TuMonkStep::OnTouch, Vec::new()).map(|_| ())
}

