                ctx.lines_as("Voice from Window", args!["^A68064This situation is very important to the reputation of the royal family and stability of the kingdom, so everyone's been very careful", "about keeping quiet.^000000"])?;
                ctx.next()?;
                ctx.lines_as("Voice from Window", args!["^A68064For now, I'll return to the kingdom and let you know if I hear of any other news. Still, since everyone needs to be so careful, it may be", "a while until I learn anything new.^000000"])?;
